-- Página de Hilary Franco, asignada a Wilson (docs/especificacion-tercer-usuario.md).
-- Requiere la migración 0016 (columna asignada_a). Se puede correr más
-- de una vez: si la página ya existe, solo la actualiza.

insert into paginas (nombre, visible, nombre_tuit, usuario_tuit, avatar_url, asignada_a)
values (
  'Hilary Franco',
  true,
  'Hilary Franco',
  '@HilaryFrancoOfi',
  'data:image/jpeg;base64,',
  'wilson'
)
on conflict (nombre) do update set
  nombre_tuit = excluded.nombre_tuit,
  usuario_tuit = excluded.usuario_tuit,
  avatar_url = excluded.avatar_url,
  asignada_a = excluded.asignada_a;
